const MOUNT_DEFAULTS = {enabled:false,itemId:'horse_c1',buyHorse:true,horseKeep:3,hpItemId:'cos_hp_potion_01',buyHp:false,hpKeep:100,healBelowPct:60};
function mountShopping(config, base=config.shop?.buyList ?? []) {
 const rows=base.map(b=>({...b})),m=config.mountTravel;
 if(!m?.enabled)return rows;
 for(const [id,keep,on]of [[m.itemId,m.horseKeep??3,m.buyHorse],[m.hpItemId,m.hpKeep??100,m.buyHp]]){
  if(!on||typeof id!=='string'||!id||!Number.isFinite(keep)||keep<=0)continue;
  const old=rows.find(b=>b.itemId===id);if(old)old.keep=Math.max(old.keep||0,Math.floor(keep));else rows.push({itemId:id,keep:Math.floor(keep)});
 }
 return rows;
}
function mountInTown(zoneId,pos){
 if(!pos)return true;
 return (MOUNT_SAFE_AREAS[zoneId]??[]).some(s=>{const sh=s.shape;if(sh?.kind!=='box')return false;const dx=pos.x-s.x-(sh.ox||0),dz=pos.z-s.z-(sh.oz||0),c=Math.cos(-(s.rotY||0)),n=Math.sin(-(s.rotY||0));return Math.abs(dx*c-dz*n)<=sh.hx&&Math.abs(dx*n+dz*c)<=sh.hz;});
}
class TravelMount {
 pending=null;retryAt=0;lastKey='';combatUntil=0;controlled=false;
 frame(t,d,q,world,log=()=>{}){
  if(t==='zone.init'){this.pending=null;this.retryAt=0;return;}
  if((t==='combat.event'&&(d.src===world.selfId||d.dst===world.selfId))||(['combat.monsterAction','auto.windup'].includes(t)&&d.targetId===world.selfId))this.combatUntil=Date.now()+20000;
  if(t==='mount.update'&&d.id===world.selfId){const transition=!!d.mount!==!!world.self.mount;if(d.mount&&this.pending)this.controlled=true;if(!d.mount)this.controlled=false;world.self.mount=d.mount;const me=world.entities.get(world.selfId);if(me)me.mount=d.mount;if(transition||this.pending){this.pending=null;this.retryAt=Date.now()+500;}}
  if(t==='combat.death'&&d.id===world.selfId){world.self.mount=null;this.pending=null;}
  if(t==='err'&&this.pending&&((d.q??q)===this.pending.q||String(d.key||'').startsWith('err.mount.'))){
   this.pending=null;this.retryAt=Date.now()+(d.key==='err.mount.combat'?20000:10000);log('horse: '+(d.key||d.code)+' - continuing; will retry');
  }
 }
 tick({config,world,wantRide,canAct,inTown=false,send,lookup,log=()=>{},now=Date.now()}){
  const cfg=config.mountTravel,self=world.self;
  if(!self||world.dead||self.dead||self.hp<=0)return false;
  const key=JSON.stringify(cfg);if(key!==this.lastKey){this.lastKey=key;this.retryAt=0;}
  if(this.pending){if(now<this.pending.until)return true;this.pending=null;this.retryAt=now+5000;log('horse: no mount confirmation - continuing; will retry');}
  const mount=self.mount;
  if(cfg?.enabled&&mount)this.controlled=true;
  if(world.aggroed?.().length)this.combatUntil=now+20000;
  if(cfg?.enabled&&mount&&mount.hp>0&&mount.maxHp>0&&mount.hp/mount.maxHp*100<(cfg.healBelowPct??60)){
   const id=cfg.hpItemId,def=lookup(id),slot=(self.inventory?.bag??[]).findIndex(s=>s?.itemId===id&&s.qty>0);
   if(def?.type==='petConsumable'&&/^cos_hp_potion_/.test(id)&&slot>=0&&world.ready('item:gpet.hp')){
    const q=send('inv.use',{bagSlot:slot,petTarget:'mount'});if(q!=null){world.onCd('item:gpet.hp',Math.max(1000,def.cooldownMs||1000));log('horse HP: '+id);}
   }
  }
  if(!canAct||now<this.retryAt)return false;

  if((!cfg?.enabled||!wantRide)&&mount&&this.controlled){const q=send('mount.dismount',{});if(q!=null){this.pending={q,until:now+3000};log('horse: dismounting at destination');return true;}return false;}
  if(!cfg?.enabled||!wantRide||mount||inTown||now<this.combatUntil)return false;
  const id=cfg.itemId,def=lookup(id),slot=(self.inventory?.bag??[]).findIndex(s=>s?.itemId===id&&s.qty>0);
  if(def?.type!=='mount'||slot<0||self.level<(def.reqLevel||1)){
   this.retryAt=now+15000;log('horse: '+(!def||def.type!=='mount'?'choose a horse':slot<0?'selected horse is not in the bag':'selected horse requires level '+def.reqLevel));return false;
  }
  const q=send('mount.use',{bagSlot:slot});if(q==null)return false;
  this.pending={q,until:now+3000};this.retryAt=now+10000;log('horse: summoning '+id);return true;
 }
}

const leaderNameKey = name => typeof name === 'string' ? name.trim().toLowerCase() : '';
function partyLeaderAllowed(config, name) {
  if (!config?.leaveIfLeaderNotAllowed) return true;
  const key = leaderNameKey(name);
  return !!key && Array.isArray(config.allowedLeaders) && config.allowedLeaders.some(n => leaderNameKey(n) === key);
}
class PartyLeaderRule {
  key = '';
  retryAt = 0;
  tick(config, party, send, log = () => {}, now = Date.now()) {
    if (!config?.leaveIfLeaderNotAllowed || !party || party.leaderCharId == null) { this.key = ''; this.retryAt = 0; return false; }
    const leader = party.members?.find(m => m.charId != null && String(m.charId) === String(party.leaderCharId));
    if (!leaderNameKey(leader?.name)) return false;
    if (partyLeaderAllowed(config, leader.name)) { this.key = ''; this.retryAt = 0; return false; }
    const key = JSON.stringify([party.partyId, party.leaderCharId, config.allowedLeaders]);
    if (key !== this.key) { this.key = key; this.retryAt = 0; }
    if (now >= this.retryAt) {
      const q = send('party.leave', {});
      if (q != null) { this.retryAt = now + 10000; log('party: leaving - leader ' + leader.name + ' is not in the allowed leaders list'); }
    }
    return true;
  }
}

  window.__SRB_BUILD = "jaderunner-0.2.0";

  const LOGCAP = 2000;
  let __logSeq = 0;
  const LOGS = (window.__SRB_LOGS ??= []);

  const logLevel = (t) => /(refus|fail|error|ERR_|cannot|panic|died|\bdead\b|blocked|giving up|stuck|unreachable)/i.test(t) ? "bad"
    : /(\bno\b|\bnot\b|wait|retry|skip|warn|stall|gave up)/i.test(t) ? "warn"
    : /(bought|\bbuy\b|loot|gather|learn|rais|arrived|found|parsed|started|equip)/i.test(t) ? "good"
    : /(walk|route|travel|move|journey|teleport|heading|\bnav\b)/i.test(t) ? "move" : "info";
  const log = (...a) => {
    console.log("%c[JadeRunner]", "color:#8f8;font-weight:bold", ...a);
    try {
      const text = a.map(x => typeof x === "string" ? x : (() => { try { return JSON.stringify(x); } catch { return String(x); } })()).join(" ");
      LOGS.push({ t: Date.now(), text, lvl: logLevel(text), n: ++__logSeq });
      if (LOGS.length > LOGCAP) LOGS.splice(0, LOGS.length - LOGCAP);
      window.__SRB_LOGSINK?.();
    } catch {}
  };

  const CACHE_OK = typeof caches !== "undefined";
  async function cachedFetch(url) {
    if (!CACHE_OK) return fetch(url);
    try {
      const cache = await caches.open("srb-assets-v1");
      const hit = await cache.match(url).catch(() => null);
      if (hit) return hit;
      const res = await fetch(url);
      if (res?.ok) { try { await cache.put(url, res.clone()); } catch {} }
      return res;
    } catch (e) { return fetch(url); }
  }
  window.__SRB_CLEAR_CACHE = async () => { if (CACHE_OK) { await caches.delete("srb-assets-v1"); log("asset cache cleared"); } };

