function campKey(home, zoneId) {
  return home && Number.isFinite(home.x) && Number.isFinite(home.z) ? `${home.zoneId ?? zoneId}:${Math.round(home.x)},${Math.round(home.z)}` : null;
}
function recordCampDeath(config, home, zoneId, entity) {
  const T = config.trainUp; if (!T?.enabled) return;
  const key = campKey(home, zoneId); if (!key) return;
  const rows = SPAWN_META?.zones?.[zoneId] ?? {};
  let mobId = Object.keys(rows).find(id => entity && (id === entity.modelKey || (rows[id].k && rows[id].k === entity.modelKey) || (entity.name && rows[id].n === entity.name)));
  if (!mobId) {
    let distance = Infinity;
    for (const [id, mob] of Object.entries(rows)) for (const pos of mob.p ?? []) {
      const d = Math.hypot(home.x - pos[0], home.z - pos[1]);
      if (!SPAWN_META?.stats?.[id]?.u && d < distance) { distance = d; mobId = id; }
    }
  }
  const evidence = T.deathCamp?.key === key ? T.deathCamp : { key, zoneId, mobId, deaths: 0 };
  evidence.mobId ??= mobId; evidence.deaths++; T.deathCamp = evidence;
  log(`camp deaths: ${evidence.deaths}/${T.deathsBeforeDown ?? 3} at the training destination`);
}
function easierCamp(zoneId, self, obs, cfg) {
  const rows = SPAWN_META.zones?.[zoneId], current = rows?.[obs.mobId];
  if (!current) return { why: "no spawn data for the current camp" };
  const choices = Object.entries(rows).filter(([id, v]) => v.l < current.l && v.l >= (cfg.minLevel ?? 0)
    && v.l <= (self?.level ?? 0) + (cfg.levelBand ?? 8) && v.p?.length && !SPAWN_META?.stats?.[id]?.u);
  choices.sort((a, b) => b[1].l - a[1].l || a[1].h - b[1].h);
  const picked = choices[0];
  if (!picked) return { why: `no lower camp in this zone above the level ${cfg.minLevel ?? 0} floor` };
  const [mobId, mob] = picked, nest = mob.p[0];
  return { mobId, name: mob.n, level: mob.l, x: nest[0], z: nest[1], radius: Math.max(20, nest[3] || 60), deathRetreat: true };
}

