function prepareSkillEquipment(config, W, entry, ensure, eqOk, buff = true) {
  const g = String(typeof entry === "string" ? entry : entry?.id ?? entry?.groupId).replace(/_\d+$/, "");
  const inv = W.self?.inventory;
  if (!inv) return false;
  const def = BUFF_META[g] ?? {};
  const requested = typeof entry === "object" ? entry.weapon : null;
  const required = !!def.reqShield;
  const usable = s => s && (s.dur ?? 1) > 0 && (itemMeta(s.itemId)?.reqLevel ?? 0) <= (W.self.level ?? 0)
    && (!itemMeta(s.itemId)?.race || !W.self.race || itemMeta(s.itemId).race === W.self.race);
  const items = [...Object.values(inv.equip ?? {}), ...(inv.bag ?? [])].filter(usable);
  const best = type => items.filter(s => itemMeta(s.itemId)?.type === type)
    .sort((a, b) => equipmentValue(b, W.self) - equipmentValue(a, W.self));
  let weapon = itemMeta(requested)?.type === "shield" ? null : requested;
  if (!weapon && SKILL_WEAPONS[g]?.length && !skillWeaponAllowed(g, inv.equip?.weapon?.itemId))
    weapon = best("weapon").find(s => skillWeaponAllowed(g, s.itemId))?.itemId;
  if (SKILL_WEAPONS[g]?.length && !skillWeaponAllowed(g, weapon ?? inv.equip?.weapon?.itemId)) {
    W.onCd(g, 15000); return false;
  }
  if (weapon && (!eqOk(weapon) || !ensure(weapon))) return false;
  const main = itemMeta(inv.equip?.weapon?.itemId);
  const canShield = !inv.equip?.weapon || (main?.type === "weapon" && !TWO_HANDED.has(main.weaponType));
  if (required && !canShield) { W.onCd(g, 15000); return false; }
  const shieldId = (typeof entry === "object" ? entry.shield : null)
    || (itemMeta(requested)?.type === "shield" ? requested : null)
    || (buff && config.useShieldForBuffs ? config.buffShield : null);
  if (!canShield && ((typeof entry === "object" && entry.shield) || itemMeta(requested)?.type === "shield")) { W.onCd(g, 15000); return false; }
  if (shieldId && itemMeta(shieldId)?.type !== "shield") { W.onCd(g, 15000); return false; }
  if (canShield && (required || shieldId || (buff && config.useShieldForBuffs))) {
    const shield = shieldId || best("shield")[0]?.itemId;
    if (!shield || !eqOk(shield)) { if (required || shieldId) { W.onCd(g, 15000); return false; } return true; }
    if (!ensure(shield)) return false;
  }
  return true;
}

