const SUPPORT_KINDS = ["buff", "heal", "dance"];
function supportNeeded(W, g, def) {
  const support = SUPPORT_SKILLS[g];
  if ((W.supportUntil?.[g] ?? 0) > Date.now()) return false;

  return (def?.kind ?? support?.kind) !== "heal" || support?.durationMs > 0 || W.hpPct() < 85;
}
function supportFired(W, d) {
  if (d.id !== W.selfId) return;
  const support = SUPPORT_SKILLS[d.skillId];
  if (support?.durationMs > 0 && (d.targetId == null || d.targetId === W.selfId))
    (W.supportUntil ??= {})[support.groupId] = Date.now() + support.durationMs;
}

