function nearestTrainingTeleport(goal, pos, zoneId) {
  if (!goal || !pos || !Number.isFinite(goal.x) || !Number.isFinite(goal.z)) return null;
  const canonical = id => String(id ?? "").replace(/_world_deprecated$|_deprecated$|_province$/g, "");
  const zone = canonical(goal.zoneId || zoneId);
  const direct = zone === canonical(zoneId) ? Math.hypot(goal.x - pos.x, goal.z - pos.z) : Infinity;
  let best = null, distance = direct - 100;
  for (const preset of TELEPORT_PRESETS) {
    if (canonical(preset.zone) !== zone) continue;
    const d = Math.hypot(goal.x - preset.pos.x, goal.z - preset.pos.z);
    if (d < distance) { best = preset; distance = d; }
  }
  return best;
}

