          const bag = world.self?.inventory?.bag ?? [];
          const room = bag.length ? bag.reduce((n, sl) => n + (sl ? (sl.itemId === item ? Math.max(0, stack - (sl.qty ?? 1)) : 0) : stack), 0) : Infinity;
          const qty = Math.max(0, Math.min(keep - have, room));
