      if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) throw new Error("Paste a bot config JSON object.");
      if (!Object.keys(parsed).some(k => Object.hasOwn(DEFAULT_AI, k))) throw new Error("This JSON contains no recognized bot settings.");
