    tileOn: "width:42px;height:42px;background:var(--surface-raised);border:1px solid var(--brass);border-radius:10px;display:flex;align-items:center;justify-content:center;cursor:pointer;position:relative;font-size:9px;line-height:1.1;text-align:center;color:var(--brass-bright);overflow:hidden;padding:1px;box-sizing:border-box;box-shadow:0 0 0 2px #c9a24d40,0 1px 2px #00000060;",
    grid: "display:flex;flex-wrap:wrap;gap:4px;max-height:220px;overflow-y:auto;overflow-x:hidden;padding:8px;background:var(--surface-sunken);border:1px solid var(--line-soft);border-radius:3px;",

