      toggle('enabled','Ride while travelling');pick('itemId','Horse','mount');toggle('buyHorse','Buy selected horse');number('horseKeep','Horse scrolls to keep',3);
      pick('hpItemId','Horse recovery kit','petConsumable');number('healBelowPct','Heal horse below HP %',60);toggle('buyHp','Buy horse recovery kits');number('hpKeep','Recovery kits to keep',100);
      box.append(ST('p','color:#aa9570;font-size:11px;','Summons outside town when combat restrictions clear. Dismounts at the destination; shopping uses the horse merchant.'));
